import {dateKey,cents} from './domain.mjs';
import {isConnected} from './runtime-store.mjs';
const modeText=(local,connected)=>isConnected()?connected:local;
import {PRODUCT_UNITS,stockQuantity,productUnitCost,procedureReturnRule,saveProduct,saveProcedure,setCatalogActive,receiveLot,editLot,adjustStock,saveQuote,approveQuote,cancelQuote,remainingSessions,completeVisit,addVisitAddendum,visitMarkings,quoteTotals,validateQuoteItem} from './operations-domain.mjs';
// Integração: renderOperationsPage(route,state) + mountOperations(host,context).
// context: getState()=>state atual; mutate(fn)=>Promise<state> que chama commit e atualiza
// o estado do app; notify(message,isError); render()=>Promise; route opcional.
// Para a consulta: inserir renderVisitOperations(state,visitId), montar no mesmo host.
// documentTemplates: [{id,name/title,active}], documentCheck(state,visit,requiredIds).
// mount retorna cleanup; não persiste fora de context.mutate e não altera notas/mapas.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value/100);
const number=value=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:4}).format(value);
const day=value=>value?String(value).split('-').reverse().join('/'):'—';
const uid=()=>crypto.randomUUID();
const attr=(name,value)=>`${name}="${esc(value)}"`;
const input=(name,label,value='',type='text',extra='')=>`<label class="op-field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,selected='',extra='')=>`<label class="op-field"><span>${esc(label)}</span><select name="${name}" ${extra}>${options.map(x=>`<option value="${esc(x.value)}" ${x.value===selected?'selected':''} ${x.disabled?'disabled':''}>${esc(x.label)}</option>`).join('')}</select></label>`;
const textarea=(name,label,value='',max=4000)=>`<label class="op-field"><span>${esc(label)}</span><textarea name="${name}" maxlength="${max}" rows="3">${esc(value)}</textarea></label>`;
const button=(label,action,id='',extra='',className='secondary')=>`<button type="button" class="${className}" data-op="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
const empty=message=>`<p class="op-empty">${esc(message)}</p>`;
const pill=(label,tone='')=>`<span class="op-status ${tone}">${esc(label)}</span>`;
const heading=(title,intro,actions='')=>`<div class="page-heading"><div><p class="eyebrow">OPERAÇÃO DA CLÍNICA</p><h1>${title}</h1><p class="subtitle">${intro}</p></div><div class="op-actions">${actions}</div></div>`;
const options=(items,label=x=>x.name)=>items.filter(x=>x.active!==false).map(x=>({value:x.id,label:label(x)}));
const decimal=centavos=>(centavos/100).toFixed(2).replace('.',',');
function marginText(q){return q.margin===null?'Sem margem calculável':`${number(q.margin)}% de contribuição estimada`;}
function lotStatus(lot,today=dateKey()){return lot.expiry<today?pill('Vencido','danger'):lot.balanceUnits<=0?pill('Sem saldo'):pill('Disponível','good');}

export function renderOperationsPage(route,state){if(route==='catalogo')return catalogPage(state);if(route==='orcamentos')return quotesPage(state);return '';}
const catalogView={section:'overview',query:'',status:'all'};
const catalogSections={procedures:{title:'Procedimentos',intro:'Valores, duração e registro de cada atendimento.',add:'Adicionar procedimento',action:'procedure-new',icon:'✦'},products:{title:'Produtos',intro:'Produtos, custos por unidade e utilização.',add:'Adicionar produto',action:'product-new',icon:'◈'},stock:{title:'Estoque',intro:'Lotes, quantidades e validade em um só lugar.',add:'Novo lote',action:'lot-new',icon:'▤'}};
const recordLabels={injectable:'Com aplicação injetável',non_injectable:'Sem aplicação injetável',simple:'Registro simples'};
const useLabels={applied:'Aplicado no paciente',material:'Material usado no atendimento'};
const fold=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
export function filterCatalog(s,section,query='',status='all'){
  const products=s.products||[],items=section==='procedures'?s.procedures||[]:section==='products'?products:s.stockLots||[],needle=fold(query.trim());
  return items.filter(x=>{if(section==='stock'){if(status==='available'&&(x.balanceUnits<=0||x.expiry<dateKey()))return false;if(status==='expired'&&x.expiry>=dateKey())return false;if(status==='empty'&&x.balanceUnits>0)return false;}else{if(status==='active'&&x.active===false)return false;if(status==='inactive'&&x.active!==false)return false;}const product=section==='stock'?products.find(p=>p.id===x.productId):null;return !needle||fold([x.name,x.category,x.brand,x.code,x.supplier,product?.name,product?.brand].filter(Boolean).join(' ')).includes(needle);});
}
function returnLabel(p){const {interval,unit}=procedureReturnRule(p);return interval?`Retorno em ${interval} ${unit==='months'?(interval===1?'mês':'meses'):(interval===1?'dia':'dias')}`:'Sem retorno configurado';}
function catalogStatusButton(kind,item){return button(item.active===false?'Reativar':'Inativar','catalog-status',item.id,`data-kind="${kind}"`,'catalog-text-button');}
function stockHistory(s){const lots=s.stockLots||[],movements=s.stockMovements||[];return `<details class="card catalog-history"><summary>Histórico do estoque <span>${movements.length} movimentos</span></summary><p class="op-note">Cada entrada, consumo e ajuste é preservado. O CSV inclui o histórico completo.</p>${button('Exportar histórico CSV','stock-export')}${movements.length?`<div class="table-wrap"><table><thead><tr><th>Data / lote</th><th>Movimento</th><th>Saldo após</th><th>Motivo</th></tr></thead><tbody>${movements.slice().reverse().slice(0,100).map(x=>{const lot=lots.find(l=>l.id===x.lotId);return`<tr><td>${esc(new Date(x.createdAt).toLocaleString('pt-BR'))}<small>${esc(lot?.code||x.lotId)}</small></td><td>${x.deltaUnits>0?'+':''}${number(stockQuantity(x.deltaUnits))} ${esc(lot?.unit)}<small>${esc(x.type)}</small></td><td>${number(stockQuantity(x.balanceAfter))}</td><td>${esc(x.reason)}</td></tr>`;}).join('')}</tbody></table></div><p class="op-note">Exibidos os últimos 100 movimentos.</p>`:empty('As movimentações aparecerão aqui.')}</details>`;}
export function renderCatalogList(s,view){const section=view.section,items=filterCatalog(s,section,view.query,view.status);if(!items.length)return empty('Nenhum registro encontrado. Confira a busca e o filtro ou adicione um cadastro.');
  let columns,rows;
  if(section==='procedures'){columns=['Procedimento','Preço / custo por sessão','Duração / retorno','Registro','Ações'];rows=items.map(x=>`<tr><td><div class="catalog-name"><span class="catalog-emoji" aria-hidden="true">${esc(x.emoji||'✦')}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.category||'Sem categoria')} · ${x.active===false?'Inativo':'Ativo'}</small></div></div></td><td>${money(x.price)}<small>Custo adicional ${money(x.cost)}</small>${x.price<x.cost?pill('Preço abaixo do custo','danger'):''}</td><td>${x.duration} min<small>${esc(returnLabel(x))}</small></td><td>${esc(recordLabels[x.recordMode||'injectable'])}${x.consentTemplateId?'<small>Termo específico vinculado</small>':''}</td><td><div class="catalog-row-actions">${button('Editar','procedure-edit',x.id)}${catalogStatusButton('procedure',x)}</div></td></tr>`).join('');}
  else if(section==='products'){columns=['Produto / marca','Unidade','Custo por unidade','Utilização','Ações'];rows=items.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small>${esc(x.brand||'Sem marca informada')} · ${x.active===false?'Inativo':'Ativo'}</small></td><td>${esc(x.unit)}</td><td>${money(x.unitCost)}</td><td>${esc(useLabels[x.usage||'applied'])}</td><td><div class="catalog-row-actions">${button('Editar','product-edit',x.id)}${catalogStatusButton('product',x)}</div></td></tr>`).join('');}
  else{columns=['Produto / lote','Validade','Saldo','Fornecedor','Ações'];rows=items.map(x=>`<tr><td><strong>${esc((s.products||[]).find(p=>p.id===x.productId)?.name||'Produto indisponível')}</strong><small>Lote ${esc(x.code)} · custo ${money(x.unitCost)} / ${esc(x.unit)}</small></td><td>${day(x.expiry)}<br>${lotStatus(x)}</td><td><strong>${number(stockQuantity(x.balanceUnits))} ${esc(x.unit)}</strong></td><td>${esc(x.supplier||'Não informado')}</td><td><div class="catalog-row-actions">${button('Editar','lot-edit',x.id)}${button('Ajustar','lot-adjust',x.id,'','catalog-text-button')}</div></td></tr>`).join('');}
  return `<p class="catalog-result-count" role="status">${items.length} ${items.length===1?'registro':'registros'}</p><div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;
}
export function catalogPage(s,view=catalogView){const current=catalogSections[view.section];
  if(!current)return `<div class="operations-root catalog-root" data-op-route="catalogo">${heading('Catálogo','Tudo o que você precisa para organizar os atendimentos.')}<div class="catalog-landing">${Object.entries(catalogSections).map(([key,c])=>{const list=key==='procedures'?s.procedures||[]:key==='products'?s.products||[]:s.stockLots||[],count=key==='stock'?list.length:list.filter(x=>x.active!==false).length;return `<button class="catalog-entry" type="button" data-op="catalog-open" data-id="${key}"><span class="catalog-entry-icon" aria-hidden="true">${c.icon}</span><span class="catalog-entry-copy"><strong>${c.title}</strong><span>${c.intro}</span><small>${count} ${key==='stock'?'lotes cadastrados':'cadastros ativos'}</small></span><span class="catalog-entry-arrow" aria-hidden="true">↗</span></button>`;}).join('')}</div><p class="catalog-local-note">${modeText('Versão em testes · dados de demonstração salvos neste navegador.','Homologação conectada · gravações confirmadas no servidor da clínica. Use dados fictícios.')}</p></div>`;
  const filters=view.section==='stock'?[{value:'all',label:'Todos os lotes'},{value:'available',label:'Com saldo e válidos'},{value:'expired',label:'Vencidos'},{value:'empty',label:'Sem saldo'}]:[{value:'all',label:'Ativos e inativos'},{value:'active',label:'Somente ativos'},{value:'inactive',label:'Somente inativos'}];
  return `<div class="operations-root catalog-root" data-op-route="catalogo"><nav class="catalog-nav" aria-label="Seções do catálogo">${button('← Catálogo','catalog-open','overview','','catalog-text-button')}${Object.entries(catalogSections).map(([key,c])=>button(c.title,'catalog-open',key,key===view.section?'aria-current="page"':'','catalog-tab')).join('')}</nav>${heading(current.title,current.intro,button('Atualizar','catalog-refresh')+button('Como cadastrar','catalog-help',view.section)+button(current.add,current.action,'','','primary'))}<section class="card catalog-list"><div class="catalog-toolbar">${input('catalogQuery','Buscar',view.query||'','search','data-catalog-search placeholder="Nome, categoria, marca ou lote…" autocomplete="off"')}${select('catalogStatus','Mostrar',filters,view.status||'all','data-catalog-filter')}</div><div data-catalog-list>${renderCatalogList(s,view)}</div></section>${view.section==='stock'?stockHistory(s):'<p class="catalog-local-note">Inativar preserva o histórico. Use o filtro para localizar e reativar um cadastro.</p>'}</div>`;
}
const paymentLabels={pix:'Pix',credit_card:'Cartão de crédito',boleto:'Boleto'};
const quoteTitle=q=>q.title||'Orçamento';
const quoteValidity=q=>q.validUntil?'Válido até '+day(q.validUntil):'Validade não definida';
const quoteQuantity=item=>item.type==='product'?`${number(item.quantity)} ${item.unit||''}`:`${item.sessions} ${item.sessions===1?'sessão':'sessões'}`;
function quotesPage(s){const quotes=s.quotes||[];return `<div class="operations-root quotes-root" data-op-route="orcamentos">${heading('Orçamentos','Procedimentos e produtos em uma proposta clara.',button('Novo orçamento','quote-new','','','primary'))}<p class="op-note">Aprovar gera uma cobrança. Recebimentos são registrados no Financeiro. Custos e contribuição aparecem apenas para a clínica.</p>${quotes.length?quotes.slice().reverse().map(q=>{const totals=quoteTotals(q.items,q.discountBps);return `<article class="card op-section op-quote"><header><div><h2>${esc(quoteTitle(q))}</h2><p>${esc(s.patients.find(p=>p.id===q.patientId)?.name)} · versão ${q.version} · ${esc(quoteValidity(q))}</p></div>${pill({rascunho:'Rascunho',aprovado:'Aprovado',cancelado:'Cancelado'}[q.status]||q.status,q.status==='aprovado'?'good':'')}</header><div class="op-summary"><article><span>Total da proposta</span><strong>${money(totals.total)}</strong></article><article><span>Custo estimado · interno</span><strong>${money(totals.cost)}</strong></article><article class="${totals.loss?'op-loss':''}"><span>Contribuição estimada · interna</span><strong>${money(totals.result)}</strong><small>${marginText(totals)}</small></article></div>${totals.loss?'<p class="op-warning">Esta proposta apresenta prejuízo estimado. Revise preço, desconto e custos antes de aprovar.</p>':''}<div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantidade</th><th>Preço ofertado</th><th>Desconto do item</th><th>Total do item</th><th>Sessões disponíveis</th></tr></thead><tbody>${q.items.map(item=>{const line=validateQuoteItem(item);return `<tr><td><strong>${esc(item.name)}</strong><small>${item.type==='product'?'Produto':'Procedimento'}</small></td><td>${esc(quoteQuantity(item))}</td><td>${money(item.unitPrice)}</td><td>${number(line.discountBps/100)}%</td><td>${money(line.total)}</td><td>${item.type==='product'?'Não se aplica':q.status==='aprovado'?remainingSessions(s,q.id,item.id):q.status==='cancelado'?'Canceladas':'Após aprovação'}</td></tr>`;}).join('')}</tbody></table></div><p class="op-note">Descontos nos itens: ${money(totals.itemDiscount)} · desconto geral: ${money(totals.discount)} (${number(totals.discountBps/100)}%).</p><div class="op-actions">${button('Ver proposta / versões','quote-view',q.id)}${button('Imprimir / PDF','quote-print',q.id)}${button('Baixar HTML','quote-html',q.id)}${q.status==='rascunho'?button('Editar','quote-edit',q.id)+button('Aprovar','quote-approve',q.id,'','primary'):''}${['rascunho','aprovado'].includes(q.status)?button('Cancelar','quote-cancel',q.id):''}</div>${q.status==='aprovado'?`<p class="op-note">Cobrança vinculada: ${esc(q.billId)}. Produtos não geram sessões; a aprovação não movimenta estoque.</p>`:''}</article>`;}).join(''):empty('Adicione procedimentos e produtos do catálogo para montar sua primeira proposta.')}</div>`;}

export function renderVisitOperations(s,visitId){const v=s.visits.find(x=>x.id===visitId);if(!v)return '';const completed=v.status==='concluido';return `<section class="card op-section operations-root" data-op-visit="${esc(v.id)}"><header><div><h2>${completed?'Consulta concluída':'Conclusão do atendimento'}</h2><p>${completed?'Registro preservado. Correções são acrescentadas como adendo.':'Revise procedimento, consumos e vínculo do orçamento antes de concluir.'}</p></div>${completed?pill('Concluída','good'):button('Revisar e concluir','visit-review',v.id,'','primary')}</header>${completed?`<div class="op-actions">${button('Adicionar adendo','visit-addendum',v.id)}</div><p class="op-note">Concluída em ${esc(new Date(v.completedAt||v.lockedAt).toLocaleString('pt-BR'))}. Custo de execução ${money(v.actualCost||0)}. ${v.quoteId?'Sessão vinculada ao orçamento.':''}</p>${(v.consumptions||[]).map(x=>`<p>${esc(x.productName)} · ${number(x.quantity)} ${esc(x.unit)} · lote ${esc(x.lotCode)} · validade ${day(x.expiry)}</p>`).join('')}${(v.addenda||[]).map(x=>`<article class="op-addendum"><strong>Adendo · ${esc(new Date(x.createdAt).toLocaleString('pt-BR'))}</strong><p>${esc(x.text).replace(/\n/g,'<br>')}</p></article>`).join('')}`:'<p class="op-note">'+modeText('Somente dados de demonstração.','Homologação conectada: use dados fictícios.')+' A confirmação baixa o estoque, utiliza sessões quando selecionadas e cria o retorno previsto configurado.</p>'}</section>`;}

export function productForm(s,id){const p=(s.products||[]).find(x=>x.id===id)||{id:uid(),name:'',unit:'mL',unitCost:0,active:true};return{title:id?'Editar produto':'Novo produto',action:'product-save',body:`<input type="hidden" name="id" value="${esc(p.id)}"><input type="hidden" name="expectedVersion" value="${p.version||0}">${input('name','Nome do produto',p.name,'text','required maxlength="120"')}${input('brand','Marca',p.brand||'','text','maxlength="100"')}<div class="op-fields">${select('unit','Unidade',PRODUCT_UNITS.map(x=>({value:x,label:x})),p.unit)}${input('unitCost','Custo por unidade (R$)',decimal(p.unitCost),'text','required inputmode="decimal"')}</div>${select('usage','Uso do produto',Object.entries(useLabels).map(([value,label])=>({value,label})),p.usage||'applied')}<details class="catalog-calculator"><summary>Calcular custo pela embalagem</summary><p class="op-note">Valor pago ÷ quantidade na unidade escolhida. O resultado é arredondado para centavos.</p><div class="op-fields">${input('packageCost','Valor da embalagem (R$)','','text','inputmode="decimal"')}${input('packageQuantity','Quantidade na embalagem','','text','inputmode="decimal"')}</div>${button('Usar custo calculado','product-calculate')}<output data-catalog-cost role="status"></output></details><label class="op-check"><input name="active" type="checkbox" ${p.active!==false?'checked':''}> Produto ativo</label><p class="op-note">A unidade de um produto que já possui lotes não pode ser trocada. O custo salvo orienta os próximos lotes; os custos históricos são preservados.</p>`};}
export function procedureForm(s,id,ctx={}){const p=(s.procedures||[]).find(x=>x.id===id)||{id:uid(),name:'',price:0,cost:0,duration:30,returnDays:0,recordMode:'simple',requiredDocumentIds:[],active:true},templates=(typeof ctx.documentTemplates==='function'?ctx.documentTemplates():ctx.documentTemplates)||s.documentTemplates||[],rule=procedureReturnRule(p),categories=[...new Set((s.procedures||[]).map(x=>x.category).filter(Boolean))],listId='categories-'+uid(),missing=(p.requiredDocumentIds||[]).filter(id=>!templates.some(t=>t.id===id));return{title:id?'Editar procedimento':'Novo procedimento',action:'procedure-save',body:`<input type="hidden" name="id" value="${esc(p.id)}"><input type="hidden" name="expectedVersion" value="${p.version||0}">${input('name','Nome do procedimento',p.name,'text','required maxlength="120"')}<div class="op-fields">${input('category','Categoria',p.category||'','text',`maxlength="80" list="${listId}"`)}<datalist id="${listId}">${categories.map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>${input('emoji','Emoji (opcional)',p.emoji||'','text','maxlength="24"')}${input('price','Preço padrão por sessão (R$)',decimal(p.price),'text','required inputmode="decimal"')}${input('cost','Custo por sessão (R$)',decimal(p.cost),'text','required inputmode="decimal"')}${input('duration','Duração (min)',p.duration,'number','required min="5" max="480"')}</div><p class="op-note">O custo por sessão é adicional aos produtos baixados no estoque. Evite incluir o mesmo material duas vezes.</p>${select('recordMode','Registro do atendimento',Object.entries(recordLabels).map(([value,label])=>({value,label})),p.recordMode||'injectable')}<div class="op-fields">${input('returnInterval','Intervalo de retorno (0 = sem retorno)',rule.interval,'number',`required min="0" max="${rule.unit==='months'?120:365}"`)}${select('returnUnit','Unidade do intervalo',[{value:'days',label:'Dias'},{value:'months',label:'Meses'}],rule.unit)}</div><p class="op-note">Meses seguem o calendário. Se o dia não existir no mês de destino, o retorno fica no último dia desse mês.</p>${select('consentTemplateId','Modelo de consentimento',[{value:'',label:'Padrão do procedimento (sem modelo específico)'},...templates.filter(t=>t.kind==='termo').map(t=>({value:t.id,label:t.name||t.title||t.id}))],p.consentTemplateId||'')}<p class="op-note">O termo escolhido será exigido na conclusão. Sem modelo específico, valem somente os documentos obrigatórios abaixo.</p><details><summary>Documentos obrigatórios adicionais</summary><fieldset class="op-fieldset"><legend>Vínculos deste procedimento</legend>${templates.length?templates.map(t=>`<label class="op-check"><input type="checkbox" name="requiredDocumentIds" value="${esc(t.id)}" ${(p.requiredDocumentIds||[]).includes(t.id)?'checked':''}> ${esc(t.name||t.title||t.id)}</label>`).join(''):empty('Nenhum modelo disponível nesta tela.')}${missing.map(id=>`<input type="hidden" name="requiredDocumentIds" value="${esc(id)}">`).join('')}${missing.length?'<p class="op-warning">Há vínculos anteriores não disponíveis nesta lista. Eles serão preservados e continuarão exigidos.</p>':''}</fieldset></details><label class="op-check"><input name="active" type="checkbox" ${p.active!==false?'checked':''}> Procedimento ativo</label>`};}
function catalogStatusForm(s,kind,id){if(!['product','procedure'].includes(kind))throw Error('Cadastro inválido.');const item=(kind==='product'?s.products:s.procedures)?.find(x=>x.id===id);if(!item)throw Error('Cadastro não encontrado.');const activating=item.active===false;return{title:`${activating?'Reativar':'Inativar'} ${kind==='product'?'produto':'procedimento'}`,action:'catalog-state-save',submit:activating?'Reativar cadastro':'Inativar cadastro',body:`<input type="hidden" name="id" value="${esc(id)}"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="expectedVersion" value="${item.version||1}"><input type="hidden" name="active" value="${activating}"><p><strong>${esc(item.name)}</strong></p><p>${activating?'O cadastro voltará a aparecer nas novas seleções.':'O cadastro sairá das novas seleções. Consultas, propostas, lotes e movimentações anteriores serão preservados.'}</p>${!activating?'<p class="op-warning">Enquanto inativo, este cadastro não poderá ser utilizado para concluir novos atendimentos, mesmo que já exista um orçamento ou lote vinculado. Você poderá reativá-lo.</p>':''}`};}
export function lotEditForm(s,id){const lot=(s.stockLots||[]).find(x=>x.id===id);if(!lot)throw Error('Lote não encontrado.');const product=(s.products||[]).find(x=>x.id===lot.productId),initial=lot.initialUnits??(s.stockMovements||[]).find(x=>x.lotId===id&&x.type==='entrada')?.deltaUnits;return{title:`Editar lote ${lot.code}`,action:'lot-edit-save',body:`<input type="hidden" name="lotId" value="${esc(id)}"><input type="hidden" name="expectedVersion" value="${lot.version}"><div class="op-fields catalog-locked">${input('originalProduct','Produto',product?.name||'Produto indisponível','text','readonly')}${input('originalCode','Lote',lot.code,'text','readonly')}${input('originalExpiry','Validade',day(lot.expiry),'text','readonly')}${input('originalQuantity','Quantidade inicial',initial===undefined?'Não disponível no histórico':`${number(stockQuantity(initial))} ${lot.unit}`,'text','readonly')}</div><p class="op-note">Os dados da entrada original e seu custo são preservados.</p>${input('supplier','Fornecedor',lot.supplier||'','text','maxlength="120"')}${input('balance',`Saldo atual (${lot.unit})`,number(stockQuantity(lot.balanceUnits)).replace(/\./g,''),'text','required inputmode="decimal"')}${textarea('reason','Motivo obrigatório se alterar o saldo','',500)}<p class="op-note">Alterar o saldo registra a diferença como um ajuste no histórico. Informe zero para retirar todo o saldo; o lote continuará registrado.</p>`};}
function catalogHelp(section){const copy={procedures:'<ol><li>Informe nome, categoria e, se desejar, emoji.</li><li>Cadastre preço, custo adicional por sessão e duração.</li><li>Escolha o tipo de registro e o retorno em dias ou meses.</li><li>Vincule um modelo de consentimento existente e os documentos exigidos.</li></ol><p>O catálogo não define doses nem protocolos clínicos automaticamente.</p>',products:'<ol><li>Informe nome e marca.</li><li>Escolha a unidade usada para medir o consumo.</li><li>Informe o custo de uma unidade, ou calcule dividindo o preço da embalagem pela quantidade.</li><li>Indique se o produto é aplicado na paciente ou usado como material do atendimento.</li></ol><p>Após criar lotes, a unidade fica protegida para preservar as quantidades históricas.</p>',stock:'<ol><li>Cadastre o produto antes de abrir um novo lote.</li><li>Informe código, validade, quantidade, custo e fornecedor.</li><li>Na edição, altere fornecedor ou saldo. Uma mudança de saldo exige motivo e gera ajuste no histórico.</li></ol><p>Produto, código, validade, quantidade inicial e custo da entrada são preservados. Lotes vencidos não aceitam aumento de saldo disponível.</p>'};return{title:`Como cadastrar · ${catalogSections[section]?.title||'Catálogo'}`,body:`<div class="catalog-help">${copy[section]||''}<p class="op-note">${modeText('Versão em testes. Salvar aqui grava dados de demonstração neste navegador.','Homologação conectada. As gravações confirmadas ficam no servidor da clínica; use dados fictícios.')}</p></div>`};}
function lotForm(s){return{title:'Entrada de lote',action:'lot-save',body:`<input type="hidden" name="id" value="${uid()}">${select('productId','Produto',[{value:'',label:'Selecione o produto'},...options(s.products||[],x=>`${x.name} · ${x.unit}`)],'','required')}<div class="op-fields">${input('code','Código do lote','','text','required maxlength="80"')}${input('expiry','Validade','','date','required')}${input('quantity','Quantidade de entrada','','text','required inputmode="decimal"')}${input('unitCost','Custo por unidade (R$)','','text','required inputmode="decimal"')}</div>${input('supplier','Fornecedor (opcional)','','text','maxlength="120"')}${textarea('reason','Motivo / documento da entrada','Entrada inicial do lote',500)}`};}
function adjustmentForm(s,id){const lot=s.stockLots.find(x=>x.id===id);if(!lot)throw Error('Lote não encontrado.');return{title:`Ajustar lote ${lot.code}`,action:'lot-adjust-save',body:`<input type="hidden" name="lotId" value="${esc(id)}"><input type="hidden" name="expectedVersion" value="${lot.version}"><p>Saldo atual: <strong>${number(stockQuantity(lot.balanceUnits))} ${esc(lot.unit)}</strong></p><div class="op-fields">${select('direction','Tipo de ajuste',[{value:'entrada',label:'Acrescentar ao saldo'},{value:'saida',label:'Retirar do saldo'}])}${input('quantity','Quantidade','','text','required inputmode="decimal"')}</div>${textarea('reason','Motivo obrigatório','',500)}<p class="op-note">O ajuste fica no histórico e não substitui a baixa feita na conclusão da consulta.</p>`};}
export function quotePickerResults(s,query='',type='all'){const needle=fold(query),items=[...(s.procedures||[]).map(x=>({...x,type:'procedure'})),...(s.products||[]).map(x=>({...x,type:'product'}))].filter(x=>x.active!==false&&(type==='all'||x.type===type)&&(!needle||fold([x.name,x.brand,x.category].join(' ')).includes(needle)));return items.length?`<div class="quote-picker-results">${items.slice(0,10).map(x=>button(`<span><strong>${esc(x.emoji||'')}${x.emoji?' ':''}${esc(x.name)}</strong><small>${x.type==='product'?`Produto · ${esc(x.unit)} · informe o preço ofertado`:`Procedimento · ${money(x.price)} / sessão`}</small></span><span aria-hidden="true">+</span>`,'quote-item-add',x.id,`data-type="${x.type}"`,'quote-picker-item')).join('')}</div>${items.length>10?'<p class="op-note">Mostrando 10 resultados. Digite mais detalhes para encontrar o item desejado.</p>':''}`:empty('Nenhum item ativo encontrado. Confira a busca ou cadastre no Catálogo.');}
export function quoteRow(s,item){const type=item.type||'procedure',product=type==='product',catalog=(product?s.products:s.procedures)?.find(x=>x.id===(product?item.productId:item.procedureId)),name=item.name||catalog?.name||'Item indisponível',unit=item.unit||catalog?.unit||'';return `<article class="quote-item-editor" data-op-row><input type="hidden" name="itemId" value="${esc(item.id)}"><input type="hidden" name="itemType" value="${esc(type)}"><input type="hidden" name="${product?'productId':'procedureId'}" value="${esc(product?item.productId:item.procedureId)}"><header><div><strong>${esc(name)}</strong><span>${product?'Produto · '+esc(unit):'Procedimento'}</span></div>${button('Remover','quote-row-remove','','aria-label="Remover '+esc(name)+'"','quote-remove')}</header>${catalog?.active===false?'<p class="op-warning">Este cadastro foi inativado. Reative-o no Catálogo ou remova o item para salvar uma revisão.</p>':''}<div class="quote-item-fields">${product?input('quantity',`Quantidade (${unit})`,String(item.quantity??1).replace('.',','),'text','required inputmode="decimal"'):input('sessions','Sessões',item.sessions??1,'number','min="1" max="1000" required')}${input('unitPrice',`Preço ofertado por ${product?'unidade':'sessão'} (R$)`,item.unitPrice===null?'':decimal(item.unitPrice),'text','required inputmode="decimal"')}${input('itemDiscount','Desconto do item (%)',number((item.discountBps||0)/100),'text','required inputmode="decimal"')}<output class="quote-line-total" data-quote-line-total aria-live="polite"></output></div><details class="quote-internal"><summary>Custo estimado · somente para a clínica</summary>${input('unitCost',`Custo por ${product?'unidade':'sessão'} (R$)`,decimal(item.unitCost),'text','required inputmode="decimal"')}<p class="op-note">${product?'O produto usa o custo estimado desta unidade.':'Inclua os materiais previstos e o custo por sessão, sem duplicar valores.'} Este campo não aparece na proposta da paciente.</p></details></article>`;}
export function quoteForm(s,id){const q=(s.quotes||[]).find(x=>x.id===id)||{id:uid(),patientId:'',title:'',validUntil:'',conditions:'',notes:'',paymentMethods:[],items:[],discountBps:0};return{title:id?'Revisar orçamento':'Novo orçamento',action:'quote-save',body:`<div class="quote-editor"><input type="hidden" name="id" value="${esc(q.id)}"><input type="hidden" name="expectedVersion" value="${q.version||0}"><div class="op-fields">${select('patientId','Paciente',[{value:'',label:'Selecione a paciente'},...options(s.patients)],q.patientId,'required')}${input('title','Título (opcional)',q.title,'text','maxlength="120"')}</div><section class="quote-picker"><h3>Adicionar itens</h3><div class="op-fields">${input('quoteSearch','Buscar no catálogo','','search','data-quote-search autocomplete="off" placeholder="Nome, categoria ou marca"')}${select('quoteType','Tipo de item',[{value:'all',label:'Procedimentos e produtos'},{value:'procedure',label:'Procedimentos'},{value:'product',label:'Produtos'}],'all','data-quote-type')}</div><div data-quote-results>${quotePickerResults(s)}</div></section><section class="quote-selected"><h3>Itens da proposta</h3><div data-op-items>${q.items.map(x=>quoteRow(s,x)).join('')}</div><p class="op-note" data-quote-empty ${q.items.length?'hidden':''}>Escolha um item no catálogo acima para começar.</p></section><div class="op-fields">${input('discount','Desconto geral (%)',number((q.discountBps||0)/100),'text','inputmode="decimal" required')}${input('validUntil','Validade (opcional)',q.validUntil||'','date')}</div><p class="op-note">O desconto geral é aplicado depois dos descontos de cada item.</p><fieldset class="quote-payments"><legend>Formas de pagamento aceitas</legend>${Object.entries(paymentLabels).map(([value,label])=>`<label class="op-check"><input type="checkbox" name="paymentMethods" value="${value}" ${(q.paymentMethods||[]).includes(value)?'checked':''}> ${label}</label>`).join('')}</fieldset>${textarea('conditions','Condições de pagamento',q.conditions)}${textarea('notes','Observações para a paciente',q.notes||'')}<output class="op-total quote-total" data-op-quote-total aria-live="polite"></output><p class="op-note">Salvar mantém um rascunho. Aprovar gera cobrança; o recebimento é separado. Produtos não geram sessões nem baixa automática de estoque. Propostas aprovadas preservam seus valores.</p></div>`};}
export function extractQuoteItems(form){return [...form.querySelectorAll('[data-op-row]')].map(row=>{const read=name=>row.querySelector(`[name=${name}]`)?.value,type=read('itemType')||'procedure';return{id:read('itemId'),type,...(type==='product'?{productId:read('productId'),quantity:read('quantity')}:{procedureId:read('procedureId'),sessions:Number(read('sessions'))}),unitPrice:cents(read('unitPrice')),unitCost:cents(read('unitCost')),discountBps:discountBps(read('itemDiscount')??'0')};});}
function discountBps(value){const normalized=String(value).trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(normalized))throw Error('Informe desconto com até duas casas decimais.');return Math.round(Number(normalized)*100);}
export function updateQuotePreview(form){const output=form.querySelector('[data-op-quote-total]');if(!output)return;const rows=[...form.querySelectorAll('[data-op-row]')],placeholder=form.querySelector('[data-quote-empty]');if(placeholder)placeholder.hidden=rows.length>0;if(!rows.length){output.textContent='Adicione itens para calcular a proposta.';return;}try{const items=extractQuoteItems(form),q=quoteTotals(items,discountBps(form.elements.discount.value));rows.forEach((row,i)=>{const line=row.querySelector('[data-quote-line-total]');if(line)line.textContent=`Total do item: ${money(validateQuoteItem(items[i]).total)}`;});output.innerHTML=`<span>Subtotal ${money(q.subtotal)} · descontos dos itens ${money(q.itemDiscount)} · desconto geral ${money(q.discount)}</span><strong>Total para a paciente ${money(q.total)}</strong><span class="quote-internal-summary">Somente para a clínica: custo estimado ${money(q.cost)} · contribuição ${money(q.result)} · ${marginText(q)}</span>${q.loss?'<span class="op-warning">Prejuízo estimado: revise o preço ou os custos.</span>':''}`;}catch(error){for(const row of rows){const line=row.querySelector('[data-quote-line-total]');if(line)line.textContent='Confira os valores';}output.textContent=error.message;}}

export function completionForm(s,id){const v=s.visits.find(x=>x.id===id);if(!v)throw Error('Consulta indisponível.');const selectedProcedure=(s.procedures||[]).find(p=>p.id===v.procedureId),unavailable=v.procedureId&&(!selectedProcedure||selectedProcedure.active===false),fixedProcedure=v.procedureSnapshot;const markings=visitMarkings(v),lots=s.stockLots||[],products=s.products||[],quoteOptions=(s.quotes||[]).filter(q=>q.patientId===v.patientId&&q.status==='aprovado').flatMap(q=>q.items.filter(x=>remainingSessions(s,q.id,x.id)>0&&(!fixedProcedure||x.procedureId===fixedProcedure.id)).map(x=>({value:JSON.stringify([q.id,x.id]),label:`${q.title} · ${x.name} · ${remainingSessions(s,q.id,x.id)} disponível(is)`})));return{title:'Revisar e concluir consulta',action:'visit-complete',body:`<input type="hidden" name="visitId" value="${esc(v.id)}"><p>${esc(s.patients.find(p=>p.id===v.patientId)?.name)} · ${day(v.date)}</p>${fixedProcedure?`<input type="hidden" name="procedureId" value="${esc(fixedProcedure.id)}"><div class="op-note" data-procedure-snapshot><strong>Procedimento preservado nesta consulta</strong><p>${esc(fixedProcedure.name)} · versão ${fixedProcedure.version}</p><p>Valor avulso ${money(fixedProcedure.price)} · custo base ${money(fixedProcedure.cost)}. Os materiais utilizados são somados ao custo na conclusão.</p><p>A versão escolhida na abertura é preservada. A seleção de orçamento abaixo oferece somente sessões deste procedimento.</p></div>`:select('procedureId','Procedimento do catálogo',[{value:'',label:'Selecione o procedimento'},...options(s.procedures||[]),...(unavailable?[{value:v.procedureId,label:(selectedProcedure?.name||v.procedureSnapshot?.name||'Procedimento anterior')+' — indisponível',disabled:true}]:[])],v.procedureId||'','required')}${unavailable?'<p class="op-warning">O procedimento escolhido no início está inativo ou indisponível. '+(fixedProcedure?'Reative esse cadastro antes de concluir; a versão selecionada será preservada.':'Reative o cadastro ou selecione outro antes de concluir.')+'</p>':''}<div class="op-fields">${select('quoteSelection','Sessão de orçamento aprovado',[{value:'',label:'Sem orçamento: cobrança do procedimento'},...quoteOptions])}${input('sessions','Sessões utilizadas',1,'number','required min="1" max="1000"')}</div><fieldset class="op-fieldset"><legend>Consumo das marcações</legend>${markings.length?markings.map((m,i)=>`<div class="op-consumption" data-op-consumption ${attr('data-photo-id',m.photoId)} ${attr('data-point-id',m.pointId)} ${attr('data-quantity',m.quantity)}><p><strong>${esc(m.region)}</strong> · ${number(m.quantity)} ${esc(m.unit)}${m.product?' · '+esc(m.product):''}</p>${select('lot-'+i,'Lote usado nesta marcação',[{value:'',label:'Selecione o lote correspondente'},...lots.filter(l=>l.unit===m.unit).map(l=>({value:l.id,label:`${products.find(p=>p.id===l.productId)?.name||'?'} · ${l.code} · ${number(stockQuantity(l.balanceUnits))} ${l.unit} · validade ${day(l.expiry)}`}))],'','required')}</div>`).join(''):empty('Nenhuma marcação com quantidade nesta consulta.')}</fieldset><fieldset class="op-fieldset"><legend>Material adicional (opcional)</legend>${select('extraLot','Lote adicional',[{value:'',label:'Sem material adicional'},...lots.map(l=>({value:l.id,label:`${products.find(p=>p.id===l.productId)?.name||'?'} · ${l.code} · ${l.unit}`}))])}<div class="op-fields">${input('extraQuantity','Quantidade','','text','inputmode="decimal"')}${input('extraReason','Descrição do uso','','text','maxlength="300"')}</div></fieldset><p class="op-note">Confirme o produto de cada lote: os nomes livres das marcações não selecionam o estoque automaticamente. O lote precisa ter unidade, validade e saldo compatíveis.</p><label class="op-check"><input type="checkbox" name="reviewed" required> Revisei procedimento, lotes, quantidades e cobrança. ${modeText('Quero concluir este atendimento de demonstração.','Quero concluir este atendimento de teste no servidor.')}</label><p class="op-warning">A conclusão preserva o registro, baixa lotes e utiliza sessões em uma única gravação. Depois, acrescente correções por adendo.</p>`};}

export function quoteDocumentHTML(state,quote){const patient=state.patients.find(x=>x.id===quote.patientId),totals=quoteTotals(quote.items,quote.discountBps);return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Proposta · ${esc(quoteTitle(quote))}</title><style>body{font:15px/1.6 system-ui,sans-serif;color:#2b2630;max-width:960px;margin:40px auto;padding:0 24px}header{border-bottom:2px solid #9b405b}h1{font-size:28px}table{border-collapse:collapse;width:100%;margin:24px 0}th,td{border-bottom:1px solid #ded5d7;text-align:left;padding:10px}th{background:#fcf4f7}.note{color:#665e68;font-size:13px}p{white-space:pre-wrap}strong.total{display:block;font-size:24px;color:#703046}.amounts{margin-left:auto;max-width:420px}small{display:block}@media print{body{margin:0;max-width:none;font-size:12px}tr{break-inside:avoid}thead{display:table-header-group}h3{break-after:avoid}}@media(max-width:620px){body{padding:0 12px}table{font-size:11px}th,td{padding:6px}}</style></head><body><header><h1>Ana Maria Jacob</h1><p>ESTÉTICA AVANÇADA · ${modeText('PILOTO LOCAL / DOCUMENTO DE DEMONSTRAÇÃO','HOMOLOGAÇÃO CONECTADA / DADOS DE TESTE')}</p></header><h2>${esc(quoteTitle(quote))}</h2><p>Paciente: ${esc(patient?.name)}\nVersão ${quote.version} · ${esc(quoteValidity(quote))} · estado ${esc(quote.status)}</p><table><thead><tr><th>Item</th><th>Quantidade</th><th>Preço ofertado</th><th>Desconto</th><th>Total do item</th></tr></thead><tbody>${quote.items.map(x=>{const line=validateQuoteItem(x);return `<tr><td>${esc(x.name)}<small>${x.type==='product'?'Produto':'Procedimento'}</small></td><td>${esc(quoteQuantity(x))}</td><td>${money(x.unitPrice)}</td><td>${number(line.discountBps/100)}%</td><td>${money(line.total)}</td></tr>`;}).join('')}</tbody></table><div class="amounts"><p>Subtotal: ${money(totals.subtotal)}\nDescontos dos itens: ${money(totals.itemDiscount)}\nDesconto geral (${number(totals.discountBps/100)}%): ${money(totals.discount)}\n<strong class="total">Total: ${money(totals.total)}</strong></p></div>${quote.paymentMethods?.length?`<h3>Formas de pagamento</h3><p>${quote.paymentMethods.map(x=>esc(paymentLabels[x]||x)).join(' · ')}</p>`:''}<h3>Condições de pagamento</h3><p>${esc(quote.conditions||'Não informadas.')}</p>${quote.notes?`<h3>Observações</h3><p>${esc(quote.notes)}</p>`:''}<p class="note">${modeText('Proposta de teste.','Proposta de teste do ambiente conectado.')} Este documento não comprova pagamento, assinatura ou consentimento clínico.</p></body></html>`;}
export function safeCSV(rows){const cell=value=>{let v=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';};return '\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n');}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function quoteDetails(q){const totals=quoteTotals(q.items,q.discountBps);return `<h3>Condições de pagamento</h3><p>${(q.paymentMethods||[]).map(x=>esc(paymentLabels[x]||x)).join(' · ')||'Formas de pagamento não definidas.'}</p><p class="op-pre">${esc(q.conditions||'Condições não informadas.')}</p>${q.notes?`<h3>Observações para a paciente</h3><p class="op-pre">${esc(q.notes)}</p>`:''}<p>Subtotal ${money(totals.subtotal)} · descontos nos itens ${money(totals.itemDiscount)} · desconto geral ${money(totals.discount)} · total ${money(totals.total)}</p><h3>Versões e decisões</h3>${(q.history||[]).map(x=>`<details><summary>Versão ${x.version} · ${esc(x.status)} · ${esc(new Date(x.at).toLocaleString('pt-BR'))}</summary>${x.snapshot?`<p>${esc(quoteTitle(x.snapshot))} · total ${money(x.snapshot.total)}</p>${x.snapshot.items.map(item=>`<p>${esc(item.name)} · ${esc(quoteQuantity(item))} × ${money(item.unitPrice)} · desconto ${number((item.discountBps||0)/100)}%</p>`).join('')}<p class="op-pre">${esc(x.snapshot.conditions)}</p><p class="op-pre">${esc(x.snapshot.notes||'')}</p><p>${(x.snapshot.paymentMethods||[]).map(p=>esc(paymentLabels[p]||p)).join(' · ')}</p>`:''}<p>${esc(x.note||'Versão preservada')}</p></details>`).join('')||empty('Primeira versão da proposta.')}<p>Versão atual: ${q.version} · ${esc(q.status)}</p>`;}

// API de ações também utilizável pelo app; dados são objetos simples normalizados pela UI.
export async function handleOperationsAction(action,data,context){const common={operationId:data.operationId||uid(),now:data.now||new Date().toISOString(),today:data.today||dateKey()},runners={
  'product-save':s=>saveProduct(s,{...common,data}), 'procedure-save':s=>saveProcedure(s,{...common,data}),
  'catalog-state-save':s=>setCatalogActive(s,{...common,data}),
  'lot-save':s=>receiveLot(s,{...common,data}), 'lot-edit-save':s=>editLot(s,{...common,data}), 'lot-adjust-save':s=>adjustStock(s,{...common,data}),
  'quote-save':s=>saveQuote(s,{...common,data}), 'quote-approve-save':s=>approveQuote(s,{...common,...data}),
  'quote-cancel-save':s=>cancelQuote(s,{...common,...data}),
  'visit-complete':s=>completeVisit(s,{...common,...data},{documentCheck:context.documentCheck}),
  'visit-addendum-save':s=>addVisitAddendum(s,{...common,...data})};
  const runner=runners[action];if(!runner)throw Error('Ação operacional desconhecida.');let result;await context.mutate(s=>{result=runner(s);});return result;
}
const mounts=new WeakMap();
export function mountOperations(host,context){mounts.get(host)?.();const controller=new AbortController();let busy=false,dialog=null;const signal=controller.signal,getState=context.getState||(()=>context.state),notify=(message,error=false)=>context.notify?.(message,error);
  function refreshCatalogList(){const list=host.querySelector('[data-catalog-list]');if(list)list.innerHTML=renderCatalogList(getState(),catalogView);}
  function renderCatalog(){host.innerHTML=catalogPage(getState());}
  function refreshQuotePicker(form){const target=form.querySelector('[data-quote-results]');if(target)target.innerHTML=quotePickerResults(getState(),form.elements.quoteSearch.value,form.elements.quoteType.value);}
  function close(){if(busy)return false;const form=dialog?.querySelector('form');if(form?.dataset.unsaved&&!confirm('Há alterações não salvas neste formulário. Descartar?'))return false;dialog?.close();dialog?.remove();dialog=null;return true;}
  function modal(config){if(context.beforeOperation?.()===false||!close())return;dialog=document.createElement('dialog');dialog.className='op-dialog';const titleId='op-title-'+uid();dialog.setAttribute('aria-labelledby',titleId);dialog.innerHTML=`<form data-op-form="${config.action||'view'}"><header><h2 id="${titleId}">${esc(config.title)}</h2>${button('Fechar','modal-close','','aria-label="Fechar janela"')}</header><input type="hidden" name="operationId" value="${uid()}"><div class="op-dialog-body">${config.body}</div><p class="op-form-error" role="alert"></p><footer>${button('Cancelar','modal-close')}${config.action?'<button class="primary" type="submit">'+(config.submit||'Salvar')+'</button>':''}</footer></form>`;host.append(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();close();},{signal});dialog.showModal();updateQuotePreview(dialog.querySelector('form'));}
  const findQuote=id=>getState().quotes?.find(x=>x.id===id)||(()=>{throw Error('Orçamento indisponível.');})();
  host.addEventListener('click',async e=>{const el=e.target.closest('[data-op]');if(!el||!host.contains(el))return;e.preventDefault();if(busy)return;const action=el.dataset.op,id=el.dataset.id,s=getState();try{
    if(action==='modal-close'){close();return;}
    if(action==='catalog-open'){if(!close())return;catalogView.section=catalogSections[id]?id:'overview';catalogView.query='';catalogView.status='all';renderCatalog();host.querySelector('h1')?.focus?.();}
    else if(action==='catalog-refresh'){if(!close())return;busy=true;el.disabled=true;try{if(context.refreshCatalog)await context.refreshCatalog();if(signal.aborted)return;renderCatalog();notify(modeText('Lista atualizada com os dados locais.','Lista atualizada com os dados do servidor.'));}finally{busy=false;if(el.isConnected)el.disabled=false;}}
    else if(action==='catalog-help')modal(catalogHelp(id));
    else if(action==='catalog-status')modal(catalogStatusForm(s,el.dataset.kind,id));
    else if(action==='product-calculate'){const form=el.closest('form'),cost=productUnitCost(cents(form.elements.packageCost.value),form.elements.packageQuantity.value);form.elements.unitCost.value=decimal(cost);form.dataset.unsaved='true';const output=form.querySelector('[data-catalog-cost]');if(output)output.textContent=`${money(cost)} por unidade${cost===0?' — valor arredondado para zero; confira se esta unidade representa o custo adequadamente.':'.'}`;}
    else if(action==='product-new'||action==='product-edit')modal(productForm(s,action==='product-edit'?id:null));
    else if(action==='procedure-new'||action==='procedure-edit')modal(procedureForm(s,action==='procedure-edit'?id:null,context));
    else if(action==='lot-new')modal(lotForm(s));
    else if(action==='lot-edit')modal(lotEditForm(s,id));
    else if(action==='lot-adjust')modal(adjustmentForm(s,id));
    else if(action==='quote-new'||action==='quote-edit')modal(quoteForm(s,action==='quote-edit'?id:null));
    else if(action==='quote-item-add'){const form=el.closest('form');if(form.querySelectorAll('[data-op-row]').length>=40)throw Error('Limite de 40 itens.');const type=el.dataset.type;if(!['procedure','product'].includes(type))throw Error('Tipo de item inválido.');const item=(type==='product'?s.products:s.procedures)?.find(x=>x.id===id&&x.active!==false);if(!item)throw Error('Cadastro indisponível. Atualize a busca.');const row=type==='product'?{id:uid(),type,productId:item.id,name:item.name,unit:item.unit,quantity:1,unitPrice:null,unitCost:item.unitCost,discountBps:0}:{id:uid(),type,procedureId:item.id,name:item.name,sessions:1,unitPrice:item.price,unitCost:item.cost,discountBps:0};form.querySelector('[data-op-items]').insertAdjacentHTML('beforeend',quoteRow(s,row));form.dataset.unsaved='true';updateQuotePreview(form);}
    else if(action==='quote-row-remove'){const form=el.closest('form');el.closest('[data-op-row]').remove();form.dataset.unsaved='true';updateQuotePreview(form);}
    else if(action==='quote-view'){const q=findQuote(id);modal({title:quoteTitle(q),body:quoteDetails(q)});}
    else if(action==='quote-approve'){const q=findQuote(id);modal({title:modeText('Aprovar proposta de demonstração','Aprovar proposta em homologação'),action:'quote-approve-save',submit:'Aprovar e vincular cobrança',body:`<input type="hidden" name="quoteId" value="${esc(id)}"><input type="hidden" name="expectedVersion" value="${q.version}"><p>${esc(quoteTitle(q))} · ${money(q.total)}</p>${q.loss?'<p class="op-warning">Atenção: custo estimado maior que o preço. Esta proposta apresenta prejuízo.</p>':''}${textarea('note','Registro da aprovação (obrigatório)',modeText('SIMULAÇÃO LOCAL — sem contratação ou pagamento real.','SIMULAÇÃO EM HOMOLOGAÇÃO — sem contratação ou pagamento real.'),1000)}<label class="op-check"><input type="checkbox" name="approved" required> Revisei valores e condições. Aprovar e gerar uma única cobrança, sem recebimento.</label>`});}
    else if(action==='quote-cancel'){const q=findQuote(id);modal({title:q.status==='aprovado'?'Cancelar orçamento e cobrança':'Cancelar rascunho',action:'quote-cancel-save',submit:'Confirmar cancelamento',body:`<input type="hidden" name="quoteId" value="${esc(id)}"><input type="hidden" name="expectedVersion" value="${q.version}"><p><strong>${esc(quoteTitle(q))}</strong> · ${money(q.total)}</p>${input('date','Data do cancelamento',dateKey(),'date','required')}${textarea('reason','Motivo obrigatório','',500)}${q.status==='aprovado'?'<p class="op-warning">Este cancelamento preserva o orçamento e cancela sua cobrança vinculada. Só é permitido sem recebimentos ativos e sem sessões utilizadas. Estorne pagamentos no Financeiro e revise atendimentos utilizados antes de continuar.</p>':'<p class="op-note">O rascunho e suas versões serão preservados no histórico.</p>'}`});}
    else if(action==='quote-html'){download(quoteDocumentHTML(s,findQuote(id)),'text/html;charset=utf-8',modeText('proposta-amj-piloto.html','proposta-amj-homologacao.html'));notify('Arquivo HTML da proposta exportado.');}
    else if(action==='quote-print'){const win=window.open('','_blank');if(!win)throw Error('Permita abrir a prévia de impressão neste navegador.');win.opener=null;win.document.open();win.document.write(quoteDocumentHTML(s,findQuote(id)));win.document.close();win.focus();win.print();notify('Prévia aberta. Escolha Salvar como PDF na impressão.');}
    else if(action==='stock-export'){const rows=[['Data','Lote','Produto','Unidade','Tipo','Quantidade','Saldo após','Custo por unidade (R$)','Motivo'],...(s.stockMovements||[]).map(m=>{const lot=(s.stockLots||[]).find(x=>x.id===m.lotId),p=(s.products||[]).find(x=>x.id===m.productId);return[m.createdAt,lot?.code,p?.name,lot?.unit,m.type,number(stockQuantity(m.deltaUnits)),number(stockQuantity(m.balanceAfter)),decimal(m.unitCost),m.reason];})];download(safeCSV(rows),'text/csv;charset=utf-8',modeText('estoque-amj-piloto.csv','estoque-amj-homologacao.csv'));notify('Histórico do estoque exportado.');}
    else if(action==='visit-review')modal(completionForm(s,id));
    else if(action==='visit-addendum')modal({title:'Adendo à consulta concluída',action:'visit-addendum-save',body:`<input type="hidden" name="visitId" value="${esc(id)}">${textarea('text','Texto do adendo','',8000)}<p class="op-note">O adendo preserva o registro original e não altera cobranças nem estoque. Ajustes financeiros e de estoque precisam de seus próprios registros.</p>`});
  }catch(error){notify(error.message,true);}},{signal});
  host.addEventListener('input',e=>{if(busy)return;if(Object.hasOwn(e.target.dataset||{},'catalogSearch')){catalogView.query=e.target.value;refreshCatalogList();return;}const form=e.target.closest('[data-op-form]');if(!form||!host.contains(form)||form.dataset.opForm==='view')return;if(Object.hasOwn(e.target.dataset||{},'quoteSearch')){refreshQuotePicker(form);return;}form.dataset.unsaved='true';if(form.dataset.opForm==='quote-save')updateQuotePreview(form);},{signal});
  host.addEventListener('change',e=>{if(busy)return;const el=e.target;if(Object.hasOwn(el.dataset||{},'catalogFilter')){catalogView.status=el.value;refreshCatalogList();return;}const form=el.closest('[data-op-form]');if(!form||!host.contains(form)||form.dataset.opForm==='view')return;if(Object.hasOwn(el.dataset||{},'quoteType')){refreshQuotePicker(form);return;}form.dataset.unsaved='true';const s=getState();if(form.dataset.opForm==='procedure-save'&&el.name==='returnUnit')form.elements.returnInterval.max=el.value==='months'?'120':'365';if(form.dataset.opForm==='quote-save')updateQuotePreview(form);if(form.dataset.opForm==='lot-save'&&el.name==='productId'){const p=s.products?.find(x=>x.id===el.value);if(p)form.elements.unitCost.value=decimal(p.unitCost);}if(form.dataset.opForm==='visit-complete'&&el.name==='quoteSelection'&&el.value){const [qId,itemId]=JSON.parse(el.value),q=s.quotes.find(x=>x.id===qId),item=q?.items.find(x=>x.id===itemId),visit=s.visits.find(v=>v.id===form.elements.visitId.value);if(!item||visit?.procedureSnapshot&&item.procedureId!==visit.procedureSnapshot.id){el.value='';notify('Escolha uma sessão do procedimento preservado nesta consulta.',true);return;}if(!visit?.procedureSnapshot)form.elements.procedureId.value=item.procedureId;}},{signal});
  host.addEventListener('submit',async e=>{const form=e.target.closest('[data-op-form]');if(!form)return;e.preventDefault();if(busy||form.dataset.opForm==='view')return;const action=form.dataset.opForm;if(action==='visit-complete'&&context.beforeOperation?.()===false)return;const values=new FormData(form),d=Object.fromEntries(values),errorNode=form.querySelector('.op-form-error');try{
    d.expectedVersion=Number(d.expectedVersion);if(action==='product-save'){d.unitCost=cents(d.unitCost);d.active=values.has('active');}
    if(action==='procedure-save'){d.price=cents(d.price);d.cost=cents(d.cost);d.duration=Number(d.duration);d.returnInterval=Number(d.returnInterval);d.active=values.has('active');d.requiredDocumentIds=values.getAll('requiredDocumentIds');}
    if(action==='catalog-state-save')d.active=d.active==='true';
    if(action==='lot-save')d.unitCost=cents(d.unitCost);
    if(action==='quote-save'){d.items=extractQuoteItems(form);d.discountBps=discountBps(d.discount);d.paymentMethods=values.getAll('paymentMethods');}
    if(action==='visit-complete'){if(!values.has('reviewed'))throw Error('Confirme a revisão.');d.sessions=Number(d.sessions);if(d.quoteSelection)[d.quoteId,d.itemId]=JSON.parse(d.quoteSelection);d.consumptions=[...form.querySelectorAll('[data-op-consumption]')].map(row=>({photoId:row.dataset.photoId,pointId:row.dataset.pointId,quantity:row.dataset.quantity,lotId:row.querySelector('select').value}));if(d.extraLot)d.consumptions.push({lotId:d.extraLot,quantity:d.extraQuantity,reason:d.extraReason});else if(d.extraQuantity)throw Error('Selecione o lote do material adicional.');}
    busy=true;form.inert=true;errorNode.textContent='';await handleOperationsAction(action,d,context);delete form.dataset.unsaved;busy=false;close();notify(action==='visit-complete'?'Consulta concluída; estoque e vínculos gravados juntos.':modeText('Registro salvo no piloto local.','Registro confirmado no servidor da clínica.'));if(context.render)await context.render();else{const route=context.route||host.querySelector('[data-op-route]')?.dataset.opRoute;if(route)host.innerHTML=renderOperationsPage(route,getState());}
  }catch(error){if(errorNode.isConnected)errorNode.textContent=error.message;else notify(error.message,true);}finally{busy=false;form.inert=false;}},{signal});
  const cleanup=()=>{controller.abort();dialog?.remove();mounts.delete(host);};mounts.set(host,cleanup);return cleanup;
}
